#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;

long long power(long long base, long long e) {
    long long r = 1;
    for (base %= MOD; e; e >>= 1, base = base * base % MOD)
        if (e & 1) r = r * base % MOD;
    return r;
}

int main() {
    long long n;
    cin >> n;
    // Inclusion-exclusion over the three monochromatic-column events: 24^n - 9*8^n + 9*2^n + 18*3^n - 24.
    long long ans = (power(24, n) - 9 * power(8, n) % MOD + 9 * power(2, n) + 18 * power(3, n) - 24) % MOD;
