import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static final long MOD = 1_000_000_007L;

    static long power(long base, long e) {
        long r = 1;
        for (base %= MOD; e > 0; e >>= 1, base = base * base % MOD)
            if ((e & 1) == 1) r = r * base % MOD;
        return r;
    }

    public static void main(String[] args) throws IOException {
        long n = nextLong();
        // Inclusion-exclusion over the three monochromatic-column events: 24^n - 9*8^n + 9*2^n + 18*3^n - 24.
        long ans = (power(24, n) - 9 * power(8, n) % MOD + 9 * power(2, n) + 18 * power(3, n) - 24) % MOD;
        System.out.println((ans + MOD) % MOD);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

const mod = 1_000_000_007

func power(base, e int64) int64 {
	r := int64(1)
	for base %= mod; e > 0; e >>= 1 {
		if e&1 == 1 {
			r = r * base % mod
		}
		base = base * base % mod
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	// Inclusion-exclusion over the three monochromatic-column events: 24^n - 9*8^n + 9*2^n + 18*3^n - 24.
	ans := (power(24, n) - 9*power(8, n)%mod + 9*power(2, n) + 18*power(3, n) - 24) % mod
	fmt.Println((ans + mod) % mod)
}
